head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
};



// 표시된 SubTotal Row 를 targetColumnID 로 찾는다.
//  - Body Table 은 thead + tbody 구조이므로 tbody 하위 tr 만 본다.
//  - 데이터 Row 사이에 예비 SubTotal tr 이 display:none 으로 미리 깔려 있으므로
//    실제 표시되는 Row(data-subtotalrowindex 보유) 만 사용한다.
//  - 비표준 속성은 data- 접두어 + 전부 소문자로 렌더된다. (targetColumnID -> data-targetcolumnid)
//  - 한 tr 의 td 순서 : [0]=RowNum, [1]=RowStatus, [2..]=일반 Cell
scwin.findSubtotalRow = function (strTargetColumnID) {
    if (typeof target1 === 'undefined' || !target1.render) {
        return null;
    }

    let trs = target1.render.querySelectorAll("tbody tr[data-targetcolumnid='" + strTargetColumnID + "']");
    for (let i = 0; i < trs.length; i++) {
        if (trs[i].getAttribute("data-subtotalrowindex") === null) continue;
        if (window.getComputedStyle(trs[i]).display === 'none') continue;
        return Array.prototype.slice.call(trs[i].querySelectorAll("td"));
    }

    return null;
}



// 두 SubTotal 의 소계 Row Cell className 을 출력한다.
scwin.btn_checkClass_onclick = function () {
    let tds1 = scwin.findSubtotalRow("dept");
    let tds2 = scwin.findSubtotalRow("region");

    // 데이터 Cell 에는 그리드 내부 컬럼 클래스가 함께 붙으므로 subtotalClass 계열 토큰만 남긴다.
    let clsOf = function (tds, idx) {
        if (!tds || !tds[idx]) return '(없음)';
        let tokens = tds[idx].className.split(/\s+/).filter(function (v) {
            return v !== '' && v.indexOf('_subtotal__column') === -1;
        });
        return tokens.join(' ');
    };

    scwin.setReturnValue("[subTotal1 / subtotalClass=tcSubAClass]");
    scwin.setReturnValue("  RowNum   : " + clsOf(tds1, 0));
    scwin.setReturnValue("  RowStatus: " + clsOf(tds1, 1));
    scwin.setReturnValue("  데이터   : " + clsOf(tds1, 2));
    scwin.setReturnValue("[subTotal2 / subtotalClass 미설정]");
    scwin.setReturnValue("  RowNum   : " + clsOf(tds2, 0) + "   <- 기대: gridSubtotalDefault gridSubtotalDefault_rowNumber");
    scwin.setReturnValue("  RowStatus: " + clsOf(tds2, 1) + "   <- 기대: gridSubtotalDefault gridSubtotalDefault_rowStatus");
    scwin.setReturnValue("  데이터   : " + clsOf(tds2, 2));
    scwin.setReturnValue("");
}
